package co.fcv.citas.auth; import co.fcv.citas.adapters.out.persistence.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*; import javax.crypto.SecretKey; import org.springframework.core.env.Environment; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey accessKey,refreshKey; private final long accessMinutes,refreshDays; // getRequiredProperty y no getProperty con valor por defecto: un secreto por defecto en el
// codigo es un secreto conocido. Sin la variable definida, la aplicacion no arranca.
public JwtService(Environment e){accessKey=key(e.getRequiredProperty("app.jwt.access-secret"));refreshKey=key(e.getRequiredProperty("app.jwt.refresh-secret"));accessMinutes=Long.parseLong(e.getProperty("app.jwt.access-minutes","15"));refreshDays=Long.parseLong(e.getProperty("app.jwt.refresh-days","7"));} private SecretKey key(String s){return Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));} String access(User u){return make(u,accessKey,accessMinutes,ChronoUnit.MINUTES,"access");} String refresh(User u){return make(u,refreshKey,refreshDays,ChronoUnit.DAYS,"refresh");} private String make(User u,SecretKey key,long amount,java.time.temporal.ChronoUnit unit,String type){Instant now=Instant.now();// "role" se conserva para los consumidores que solo necesitan uno; "roles" lleva todos,
// porque user_roles es N:M y un mismo usuario puede tener varios.
return Jwts.builder().id(UUID.randomUUID().toString()).subject(u.getId().toString()).claim("role",u.getPrimaryRole()).claim("roles",u.getRoleCodes()).claim("type",type).issuedAt(Date.from(now)).expiration(Date.from(now.plus(amount,unit))).signWith(key).compact();} long accessSeconds(){return accessMinutes*60;} public Claims parseAccess(String t){return Jwts.parser().verifyWith(accessKey).build().parseSignedClaims(t).getPayload();} public Claims parseRefresh(String t){return Jwts.parser().verifyWith(refreshKey).build().parseSignedClaims(t).getPayload();} }
